S=/private/tmp/claude-502/-Volumes-X-SSD-2025-Users-narrowchannel-Desktop-indii-music-founder/1e0a63ba-0c56-4351-82f4-9fdef6f9fae1/scratchpad; cat > $S/jev-mcp.mjs <<'EOF'
import fs from 'node:fs';
const envPath = '/Volumes/X SSD 2025/Users/narrowchannel/Desktop/indii-music-founder/.env';
const key = fs.readFileSync(envPath,'utf8').split('\n').find(l=>l.startsWith('TYPESAFE_API_KEY='))?.slice(17).trim().replace(/^["']|["']$/g,'');
if(!key){console.error('no key');process.exit(1);}
const src = fs.readFileSync(process.argv[2],'utf8');
// server facts so Jev can judge accuracy
const facts = JSON.parse(fs.readFileSync(process.argv[3],'utf8'));
const items=[]; const re=/name: '([a-z_]+)',\s*\n\s*description: (["'])((?:\\.|(?!\2).)*)\2/g; let m;
while((m=re.exec(src))) items.push({tool:m[1],text:m[3].replace(/\\'/g,"'"),line:src.slice(0,m.index).split('\n').length+1});
const qs={};
for(const it of items){
  qs[it.tool+'__voice']={type:'choice',instructions:{task:'Classify this function description, which an assistant model reads when deciding whether to call the tool for an independent musician. Judge the wording only.',tool:it.tool,description:it.text},
   criteria:{clean:'plain, direct, no problems',ai_hype:'AI/neural/intelligence hype',plumbing:'names internal vendors, databases, models or ticket numbers that the model does not need (industry standards like ISRC, UPC, CWR, The MLC are fine)',aggressive_or_mystical:'swarm/command/supremacy or DNA/alchemy/soul language',jargon_or_verbose:'unclear jargon or wordier than needed'}};
  qs[it.tool+'__fit']={type:'choice',instructions:{task:'Compare the description a model sees with what the server tool actually does. Would the model misjudge when to call it or overstate the result to the artist?',tool:it.tool,description:it.text,server_behavior:facts[it.tool]},
   criteria:{accurate:'description matches the server behavior closely enough to call it at the right time and report honestly',overstates:'description implies the tool does more than it does (e.g. a full check, signatures, delivery, payment)',unclear_when:'description is accurate but leaves the model unsure when to call it or what it returns'}};
}
const r=await fetch('https://api.typesafe.ai/v1/systemone',{method:'POST',headers:{Authorization:`Bearer ${key}`,'Content-Type':'application/json'},body:JSON.stringify({state:{product:'indii, a music business platform for independent artists; descriptions are model-facing tool declarations'},questions:qs,model:'jev-latest'})});
const j=await r.json(); if(!r.ok){console.error(r.status,JSON.stringify(j).slice(0,400));process.exit(1);}
let flagged=0;
for(const it of items){ const v=j.answers[it.tool+'__voice'], f=j.answers[it.tool+'__fit'];
  const bad=(v.choice!=='clean'&&v.confidence>=0.65)||(f.choice!=='accurate'&&f.confidence>=0.65); if(bad) flagged++;
  console.log(`${bad?'FLAG':'ok  '} L${it.line} ${it.tool}: voice=${v.choice}(${v.confidence?.toFixed(2)}) fit=${f.choice}(${f.confidence?.toFixed(2)})`);}
console.log(`calls=1 tokens=${j.usage?.input_tokens}/${j.usage?.output_tokens} flagged=${flagged}/${items.length}`);
EOF
cat > $S/facts.json <<'EOF'
{"fetch_brand_kit":"Reads the signed-in artist's saved brand aesthetic (colors, typography, tone) from their profile.",
"queue_release_canvas_render":"Records a render job for an owned release and queues a looping canvas MP4 made from the release cover art synced to the artist's own uploaded audio. Never generates music. Returns a queued job id; does not post anywhere.",
"audit_asset_resolutions":"Inspects the bytes of the release's cover artwork only and compares against the store cover-art baseline (dimensions, format). Does not check audio or video.",
"draft_dsp_metadata":"Drafts a store metadata XML fragment. Not delivery-ready: no schema validation, recipient, asset or deal blocks. Draft mode defaults missing duration/releaseDate and flags deliveryReady:false; delivery mode errors if they are missing. Nothing is sent.",
"calculate_recoupment":"Calculates recoupment from recorded earnings and recoupment balance ledgers for an owned release.",
"stage_stripe_payouts":"Stages a royalty payout figure for one month from recorded earnings and recoupment ledgers, checks each recipient's payout account status, for later human approval. Creates no transfer or payout.",
"register_split_sheet":"Validates percentages sum to 100 and records an unsigned split sheet with a hashed text copy. Does NOT collect collaborator signatures or make a PDF contract. Status recorded_unsigned.",
"draft_cwr_registration":"Builds a CWR 2.1/2.2 export file for an owned release from explicit sender, writer, publisher and share data. Missing facts block export. Structural validation is not society verification; nothing is transmitted. Status draft_unsubmitted.",
"audit_sample_clearance":"Reports sample/interpolation clearance status from declared track metadata fields only. No audio fingerprinting; undeclared samples are not detected."}
EOF
